    db.crear_clase('Lejana', 'Leo', AHORA + timedelta(hours=24, seconds=1))
    for clase in db.clases():
        db.crear_reserva(socio['id'], clase['id'], AHORA)
    r = llamar(cliente)
    assert r.json() == {'enviados': 1}
    [correo] = db.correos()
    assert f"Exacta el" in correo['asunto']
    assert inclusive['nombre'] == 'Exacta'


